minimal_example_no_lang.js:
addFillBlank({
  code: "x __op__ 5",
  blanks: [{ id: "op", answer: ":=" }],
  explain: "Το := δηλώνει ΚΑΙ αρχικοποιεί μια νέα μεταβλητή σε ένα βήμα."
})

example_with_lang_coloring.js:
addFillBlank({
  code: "func main() {\n  ch := make(chan int)\n  go func() { ch __send__ 42 }()\n  v := __recv__ ch\n  fmt.Println(v)\n}",
  blanks: [
    { id: "send", answer: "<-" },
    { id: "recv", answer: "<-" }
  ],
  explain: "Το <- στέλνει σε ένα channel όταν είναι στα δεξιά, και λαμβάνει όταν είναι στα αριστερά μιας ανάθεσης.",
  lang: "go"
})

example_array_form_with_opts.js:
addFillBlank(
  [item1, item2],
  { label: "Άσκηση: Channels", note: "Συμπλήρωσε τα κενά." }
)
